<?php $title=$record['title'];$labels=['draft'=>'Entwurf','scheduled'=>'Geplant','published'=>'Veröffentlicht','archived'=>'Archiviert']; ?>
<div class="page-header split"><div><p class="eyebrow">Mitteilung · Version <?= (int)$record['revision'] ?></p><h1><?= e($record['title']) ?></h1><p><?= e($labels[$record['status']]??$record['status']) ?> · <?= e($record['priority']==='important'?'Wichtig':'Info') ?></p></div><div class="inline-actions"><a class="button ghost" href="<?= e(can('messages.manage')?url('announcements/manage'):url('announcements')) ?>">Zurück</a><?php if(can('messages.manage')):?><a class="button primary" href="<?= e(url('announcements/'.$record['id'].'/edit')) ?>">Bearbeiten</a><?php endif;?></div></div>
<div class="panel"><div class="prose"><?= nl2br(e($record['body'])) ?></div><?php if($record['attachments']):?><h3 class="section-title">Anhänge</h3><div class="timeline-list"><?php foreach($record['attachments'] as $a):?><div class="timeline-item"><a href="<?= e(url('attachments/'.$a['id'].'/download')) ?>"><strong><?= e($a['original_name']) ?></strong></a><small class="table-sub"><?= e(format_datetime($a['uploaded_at'])) ?> · <?= e($a['uploader_name']??'') ?></small></div><?php endforeach;?></div><?php endif;?></div>
<?php if($record['status']==='published'&&$record['require_ack']):?><?php $me=array_values(array_filter($record['reads'],fn($x)=>(int)$x['user_id']===(int)\WKS\Core\Auth::id()));$confirmed=$me&&$me[0]['confirmed_at'];?><div class="panel"><h2>Lesebestätigung</h2><?php if($confirmed):?><div class="notice success">Bestätigt am <?= e(format_datetime($me[0]['confirmed_at'])) ?>.</div><?php else:?><form method="post" action="<?= e(url('announcements/'.$record['id'].'/confirm')) ?>"><?= csrf_field() ?><button class="button primary" type="submit">Mitteilung gelesen und verstanden</button></form><?php endif;?></div><?php endif;?>
<?php if(can('messages.manage')&&$record['require_ack']):?><div class="panel"><div class="panel-header"><div><h2>Lesestatus</h2><p>Bestätigungen der aktuellen Version <?= (int)$record['revision'] ?>.</p></div></div><div class="table-wrap"><table><thead><tr><th>Benutzer</th><th>Gelesen</th><th>Bestätigt</th></tr></thead><tbody><?php foreach($record['reads'] as $r):?><tr><td><?= e($r['user_name']) ?></td><td><?= e(format_datetime($r['read_at'])) ?></td><td><?= e(format_datetime($r['confirmed_at'])) ?></td></tr><?php endforeach;?><?php if($record['reads']===[]):?><tr><td colspan="3" class="empty">Noch keine Lesedaten für diese Version.</td></tr><?php endif;?></tbody></table></div></div><?php endif;?>
